WITH parsed AS (SELECT id, plan, tier_prices, discounts, TRANSFORM(tier_prices, (p, i) -> ROUND(p * tier_limits[i], 2)) AS tier_revenue_caps, AGGREGATE(tier_prices, 0.0D, (acc, p) -> acc + p, acc -> ROUND(acc / SIZE(tier_prices), 2)) AS avg_tier_price FROM price_tiers) SELECT id, plan, tier_prices, discounts, tier_revenue_caps, avg_tier_price, LAST_VALUE(avg_tier_price) IGNORE NULLS OVER w_grp AS last_known_avg_tier_price, LEAD(avg_tier_price, 1) OVER w_recent AS next_avg_tier_price, ROW_NUMBER() OVER w_recent AS seq_no, LAST_VALUE(avg_tier_price) IGNORE NULLS OVER w_grp AS last_known_avg_tier_price_2 FROM parsed WINDOW w_grp AS (PARTITION BY plan ORDER BY avg_tier_price, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW), w_recent AS (PARTITION BY plan ORDER BY avg_tier_price, id)
